fields.InputDefinition:
{
  "goal": "Run a saved query and view its results. In the LEFT sidebar 'Search queries...' box (NOT the global Ctrl+K box), type 'Entities with Field Counts' and select that query. If it is not present, pick any other query that shows NO required-parameter asterisks (e.g. 'Server Installed Version History'). AVOID queries marked 'Pending' or showing required-parameter asterisks. Click Run and verify results display in a table with data rows. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "A no-parameter Approved query was located (via the 'Search queries...' box or a visible folder) and run",
    "Query results are displayed in a table with data rows",
    "No error messages, blank screens, or crash pages"
  ]
}
